<?php

namespace Vapi\Types;

use Vapi\Core\Json\JsonSerializableType;
use Vapi\Core\Json\JsonProperty;

class SimulationOnboardingCoverageGapDto extends JsonSerializableType
{
    /**
     * @var string $requirementId Requirement the gap is for, e.g. `R4`.
     */
    #[JsonProperty('requirementId')]
    public string $requirementId;

    /**
     * @var value-of<SimulationOnboardingCoverageGapDtoReason> $reason Why no simulation covers it. `failed` and `budget` gaps are regenerated by an edit with `retryFailed`.
     */
    #[JsonProperty('reason')]
    public string $reason;

    /**
     * @var ?string $detail A short explanation for the user.
     */
    #[JsonProperty('detail')]
    public ?string $detail;

    /**
     * @param array{
     *   requirementId: string,
     *   reason: value-of<SimulationOnboardingCoverageGapDtoReason>,
     *   detail?: ?string,
     * } $values
     */
    public function __construct(
        array $values,
    ) {
        $this->requirementId = $values['requirementId'];
        $this->reason = $values['reason'];
        $this->detail = $values['detail'] ?? null;
    }

    /**
     * @return string
     */
    public function __toString(): string
    {
        return $this->toJson();
    }
}
